{"name": "calculate_precision", "parameters": {"TP": 40, "FP": 10}}; {"name": "calculate_recall", "parameters": {"TP": 40, "FN": 20}}

def calculate_precision(TP, FP):
    return round(TP / (TP + FP), 3)

def calculate_recall(TP, FN):
    return round(TP / (TP + FN), 3)

